UPDATE CL_ACTIVITY_BOARD
   SET ACTIVITY_TITLE = #{title},
       ACTIVITY_CONTENT = #{content}
WHERE ACTIVITY_NO = #{id}

UPDATE CL_ACTIVITY_CERTIFICATION
   SET CERTIFICATION_NO = #{category}
WHERE ACTIVITY_BOARD_NO = #{id}

UPDATE CL_ACTIVITY_ATTACHMENT
   SET FILE_PATH = #{filePath}
WHERE REF_BNO = #{id}
  AND THUMBNAIL_YN = 'Y'
